require_once __DIR__.'/core.php';require_once __DIR__.'/maintenance.php';tt_require_login();if($_SERVER['REQUEST_METHOD']!=='POST')tt_fail('Deletion requires a POST request.',405,'Delete');$id=(int)($_POST['post_id']??0);if($id<=0)tt_fail('Invalid post id.',400,'Delete');$db=tt_db_open(true);$s=tt_prepare($db,'SELECT `name` FROM `posts` WHERE `id`=?');$s->bind_param('i',$id);$s->execute();$s->bind_result($owner);if(!$s->fetch()){$s->close();$db->close();tt_fail('Post not found.',404,'Delete');}$s->close();if(!hash_equals((string)$owner,(string)$_SESSION['name'])){$db->close();tt_fail('You can only delete your own posts.',403,'Delete');}tt_delete_post($db,$id,false);$db->close();header('Location: post.php?deleted=1');exit;
